type Platform = "macos" | "windows" | "linux";

type PlatformCheckType = "aix" | "android" | "darwin" | "freebsd" | "haiku" | "linux" | "openbsd" | "sunos" | "win32" | "cygwin" | "netbsd";


interface OnboardingCampaign {
  id: string;
  name: string;
  html: string[];
  css: string[];
  js: string[];
  assets: string[];
  start_time: string;   // unix seconds, but stored as a string in your JSON
  end_time: string;
  platforms: Platform[];
}

interface OnboardingCountryEntry {
  location: string;                  // "world", "India", ...
  language: string[];
  payload: OnboardingCampaign[][];   // array of arrays, as in your JSON
}

interface OnboardingJsonType {
  "getOnboarding" : boolean;
  "api-global-version": string;
  "api-version": string;
  "app-version-range": [string, string];   // [min, max]
  country: OnboardingCountryEntry[];
}

interface onBoardingJsonReturnType {
  latestConfig : OnboardingJsonType;
  location : string | null;
}



export type {OnboardingJsonType,onBoardingJsonReturnType,PlatformCheckType,OnboardingCountryEntry,}